{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale each input embedding by 1/sqrt(1+c), where c counts earlier occurrences in the supplied causal sequence window. This may reduce repeated-item dominance while preserving embedding parameters, GRU topology, readout, loss and optimizer. The generated predictor imports this same model class, so inference uses identical features without checkpoint changes.",
      "edits": [
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def input_features(self, seq: torch.Tensor) -> torch.Tensor:\n        # Count only earlier matching items within the available causal window.\n        matches = seq.unsqueeze(2).eq(seq.unsqueeze(1))\n        earlier_counts = torch.tril(matches, diagonal=-1).sum(dim=-1, dtype=torch.float32)\n        scales = torch.rsqrt(1.0 + earlier_counts)\n        scales = scales * seq.ne(0).to(scales.dtype)\n        emb = self.item_emb(seq)\n        return self.dropout(emb * scales.to(emb.dtype).unsqueeze(-1))\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.input_features(seq)"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.input_features(seq)"
        }
      ]
    }
  ],
  "change_summary": "Add deterministic causal repeat-frequency scaling to GRU inputs during training and prediction; retain one model per category and all existing training settings."
}
